from collections import deque
# graph distance from each 2 cell to any source component via 4-neighbor 2s. initialize every 2 adjacent to color patch with source dominant label.
from collections import defaultdict
sources=[]
for r,c in zip(*np.where(G==2)):
 labs_adj=[]
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  rr,cc=r+dr,c+dc
  if 0<=rr<16 and 0<=cc<16 and G[rr,cc] in (4,5): labs_adj.append(int(G[rr,cc]))
 if labs_adj:
  # choose majority among adjacent colored pixels
  sources.append((r,c,Counter(labs_adj).most_common(1)[0][0]))
print(sources)
# BFS individually
all_dist={}
for lab in [4,5]:
 d=np.full((16,16),999,int); q=deque()
 for r,c,v in sources:
  if v==lab: d[r,c]=0;q.append((r,c))
 while q:
  r,c=q.popleft()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<16 and 0<=cc<16 and G[rr,cc]==2 and d[rr,cc]>d[r,c]+1:
    d[rr,cc]=d[r,c]+1;q.append((rr,cc))
 all_dist[lab]=d
O2=G.copy()
for r,c in zip(*np.where(G==2)):
 d4,d5=all_dist[4][r,c],all_dist[5][r,c]
 O2[r,c] = 4 if d4<d5 else (5 if d5<d4 else 2)
print('tie count',sum(1 for r,c in zip(*np.where(G==2)) if all_dist[4][r,c]==all_dist[5][r,c]))
print('\n'.join(' '.join(map(str,row)) for row in O2))

# sources by adjacent non-2 CC's modal color
src=[]
for r,c in zip(*np.where(G==2)):
 labs_touch=set()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  rr,cc=r+dr,c+dc
  if 0<=rr<16 and 0<=cc<16 and G[rr,cc]!=2: labs_touch.add(int(labs[rr,cc]))
 for comp in labs_touch:
  vals=G[labs==comp]
  if len(vals) and np.all(vals!=1):
   mode=Counter(vals).most_common(1)[0][0]
   src.append((r,c,int(mode)))
print(src)
# seeds duplicate can occur; BFS by color
D={}
for color in (4,5):
 d=np.full((16,16),999,int);q=deque()
 for r,c,v in src:
  if v==color and d[r,c]!=0: d[r,c]=0;q.append((r,c))
 while q:
  r,c=q.popleft()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<16 and 0<=cc<16 and G[rr,cc]==2 and d[rr,cc]>d[r,c]+1:
    d[rr,cc]=d[r,c]+1;q.append((rr,cc))
 D[color]=d
O3=G.copy()
for r,c in zip(*np.where(G==2)):
 a,b=D[4][r,c],D[5][r,c]
 O3[r,c]=4 if a<b else 5 if b<a else 2
print('ties',[(int(r),int(c)) for r,c in zip(*np.where((G==2)&(D[4]==D[5])))])
