O4=G.copy()
from collections import Counter
for r,c in zip(*np.where(G==2)):
 vals=[]
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   if (dr or dc) and 0<=r+dr<16 and 0<=c+dc<16 and G[r+dr,c+dc]!=2:
    vals.append(int(G[r+dr,c+dc]))
 counts=Counter(vals)
 if counts:
  m=max(counts.values()); winners=[k for k,v in counts.items() if v==m]
  if len(winners)==1: O4[r,c]=winners[0]
print('\n'.join(' '.join(map(str,row)) for row in O4))

